      codigoInicial: "import sqlite3\n\nconn = sqlite3.connect(\":memory:\")\nconn.executescript(\"\"\"\nCREATE TABLE clientes (id INTEGER PRIMARY KEY, nombre TEXT, ciudad TEXT, plan TEXT);\nCREATE TABLE productos (id INTEGER PRIMARY KEY, nombre TEXT, categoria TEXT, precio REAL);\nCREATE TABLE pedidos (id INTEGER PRIMARY KEY, cliente_id INTEGER, producto_id INTEGER, cantidad INTEGER, fecha TEXT);\n\nINSERT INTO clientes VALUES\n  (1, 'Ana', 'Bogota', 'Premium'), (2, 'Luis', 'Medellin', 'Basico'), (3, 'Marta', 'Bogota', 'Basico'),\n  (4, 'Pedro', 'Cali', 'Premium'), (5, 'Sofia', 'Medellin', 'Estandar'), (6, 'Diego', 'Bogota', 'Estandar');\nINSERT INTO productos VALUES\n  (1, 'Laptop', 'Electronica', 2500), (2, 'Mouse', 'Accesorios', 50), (3, 'Teclado', 'Accesorios', 120),\n  (4, 'Monitor', 'Electronica', 800), (5, 'Audifonos', 'Accesorios', 150);\nINSERT INTO pedidos VALUES\n  (1, 1, 1, 1, '2024-01-10'), (2, 1, 2, 2, '2024-01-12'), (3, 2, 3, 1, '2024-01-15'),\n  (4, 3, 4, 2, '2024-02-01'), (5, 4, 1, 1, '2024-02-05'), (6, 5, 5, 3, '2024-02-10'),\n  (7, 2, 2, 4, '2024-02-14'), (8, 1, 5, 1, '2024-03-01'), (9, 3, 2, 5, '2024-03-03'),\n  (10, 5, 4, 1, '2024-03-09');\n\"\"\")\n\nconn.executescript(\"\"\"\nCREATE TABLE empleados (id INTEGER PRIMARY KEY, nombre TEXT, depto TEXT, salario INTEGER, jefe_id INTEGER, ingreso TEXT);\nINSERT INTO empleados VALUES\n  (1, 'Carla', 'Direccion', 9000, NULL, '2019-03-01'), (2, 'Andres', 'Ventas', 5200, 1, '2020-07-15'),\n  (3, 'Lucia', 'Ventas', 4800, 2, '2021-02-01'), (4, 'Mateo', 'Ventas', 4800, 2, '2022-09-12'),\n  (5, 'Paula', 'Datos', 6500, 1, '2020-01-20'), (6, 'Hugo', 'Datos', 5800, 5, '2021-11-03'),\n  (7, 'Elena', 'Datos', 5800, 5, '2023-04-17'), (8, 'Raul', 'Soporte', 3500, 1, '2022-05-30'),\n  (9, 'Nora', 'Soporte', 3900, 8, '2023-01-09');\n\"\"\")\n\nsql = \"\"   # escribe aquí tu consulta\nfilas = conn.execute(sql).fetchall() if sql else []\nprint(filas)",
      solucion: "import sqlite3\n\nconn = sqlite3.connect(\":memory:\")\nconn.executescript(\"\"\"\nCREATE TABLE clientes (id INTEGER PRIMARY KEY, nombre TEXT, ciudad TEXT, plan TEXT);\nCREATE TABLE productos (id INTEGER PRIMARY KEY, nombre TEXT, categoria TEXT, precio REAL);\nCREATE TABLE pedidos (id INTEGER PRIMARY KEY, cliente_id INTEGER, producto_id INTEGER, cantidad INTEGER, fecha TEXT);\n\nINSERT INTO clientes VALUES\n  (1, 'Ana', 'Bogota', 'Premium'), (2, 'Luis', 'Medellin', 'Basico'), (3, 'Marta', 'Bogota', 'Basico'),\n  (4, 'Pedro', 'Cali', 'Premium'), (5, 'Sofia', 'Medellin', 'Estandar'), (6, 'Diego', 'Bogota', 'Estandar');\nINSERT INTO productos VALUES\n  (1, 'Laptop', 'Electronica', 2500), (2, 'Mouse', 'Accesorios', 50), (3, 'Teclado', 'Accesorios', 120),\n  (4, 'Monitor', 'Electronica', 800), (5, 'Audifonos', 'Accesorios', 150);\nINSERT INTO pedidos VALUES\n  (1, 1, 1, 1, '2024-01-10'), (2, 1, 2, 2, '2024-01-12'), (3, 2, 3, 1, '2024-01-15'),\n  (4, 3, 4, 2, '2024-02-01'), (5, 4, 1, 1, '2024-02-05'), (6, 5, 5, 3, '2024-02-10'),\n  (7, 2, 2, 4, '2024-02-14'), (8, 1, 5, 1, '2024-03-01'), (9, 3, 2, 5, '2024-03-03'),\n  (10, 5, 4, 1, '2024-03-09');\n\"\"\")\n\nconn.executescript(\"\"\"\nCREATE TABLE empleados (id INTEGER PRIMARY KEY, nombre TEXT, depto TEXT, salario INTEGER, jefe_id INTEGER, ingreso TEXT);\nINSERT INTO empleados VALUES\n  (1, 'Carla', 'Direccion', 9000, NULL, '2019-03-01'), (2, 'Andres', 'Ventas', 5200, 1, '2020-07-15'),\n  (3, 'Lucia', 'Ventas', 4800, 2, '2021-02-01'), (4, 'Mateo', 'Ventas', 4800, 2, '2022-09-12'),\n  (5, 'Paula', 'Datos', 6500, 1, '2020-01-20'), (6, 'Hugo', 'Datos', 5800, 5, '2021-11-03'),\n  (7, 'Elena', 'Datos', 5800, 5, '2023-04-17'), (8, 'Raul', 'Soporte', 3500, 1, '2022-05-30'),\n  (9, 'Nora', 'Soporte', 3900, 8, '2023-01-09');\n\"\"\")\n\nsql = \"\"\"\nWITH r AS (\n    SELECT depto, nombre,\n           ROW_NUMBER() OVER (PARTITION BY depto ORDER BY salario DESC, id) AS n\n    FROM empleados\n)\nSELECT depto, nombre FROM r WHERE n = 1 ORDER BY depto\n\"\"\"\nfilas = conn.execute(sql).fetchall()\nprint(filas)",
